//! Every setting the editor shows, from BOSS Tone Studio's own tables
//! (`settings_gen.rs`, generated by `scripts/bts_settings.py --rust`; the
//! same data as docs/settings.md). Settings the app already verified on the
//! amp (`PARAMS`, `modfx`) keep their definitions and names.

use std::sync::LazyLock;

use crate::params::{all_params, ParamDef, PARAMS};

#[rustfmt::skip]
#[path = "settings_gen.rs"]
mod settings_gen;

pub use settings_gen::{GenBlock, GenSetting, BLOCKS};

/// Settings that failed `katana-cli check-settings` on the amp, left out of
/// the editor's panels. Empty: all 1222 passed on 2026-11-11 (docs/protocol.md,
/// "Settings check").
pub const EXCLUDED: &[&str] = &[];

fn leak(s: String) -> &'static str {
    Box::leak(s.into_boxed_str())
}

/// One parameter per instance and setting, named `<instance>-<key>`
/// (e.g. `delay4-time`), except where `PARAMS` or `modfx` already has one.
pub(crate) static GENERATED: LazyLock<Vec<ParamDef>> = LazyLock::new(|| {
    let known = |a: u32| PARAMS.iter().chain(crate::modfx::GENERATED.iter()).any(|p| p.addr == a);
    let mut out = Vec::new();
    for b in BLOCKS {
        for &(inst, base) in b.inst {
            for s in b.settings {
                let addr = base + s.offset;
                if known(addr) {
                    continue;
                }
                out.push(ParamDef {
                    name: leak(format!("{inst}-{}", s.key)),
                    addr,
                    encoding: s.encoding,
                    min: s.min,
                    max: s.max,
                    values: s.values,
                    ofs: s.ofs,
                    format: s.format,
                });
            }
        }
    }
    out
});

/// The settings this module adds (not verified on the amp before).
pub fn generated() -> &'static [ParamDef] {
    &GENERATED
}

/// The table whose instance holds this address, e.g. `"DELAY"`.
pub fn table_of(addr: u32) -> Option<&'static str> {
    BLOCKS
        .iter()
        .find(|b| b.inst.iter().any(|&(_, base)| b.settings.iter().any(|s| base + s.offset == addr)))
        .map(|b| b.table)
}

/// The parameter (verified or generated) at a linear address.
pub fn def_at(addr: u32) -> Option<&'static ParamDef> {
    all_params().iter().find(|p| p.addr == addr)
}

/// A block layout by its Tone Studio table name, e.g. `"REVERB"`.
pub fn gen_block(table: &str) -> &'static GenBlock {
    BLOCKS.iter().find(|b| b.table == table).unwrap_or_else(|| panic!("no settings table {table}"))
}

/// Setting `key` of instance `inst` (0-based) of `table`, e.g.
/// `setting("REVERB", 0, "layer-mode")`.
pub fn setting(table: &str, inst: usize, key: &str) -> Option<&'static ParamDef> {
    let b = gen_block(table);
    let &(_, base) = b.inst.get(inst)?;
    def_at(base + b.settings.iter().find(|s| s.key == key)?.offset)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::device::addr;
    use crate::params::PARAMS;

    fn gen_at(a: u32) -> Option<&'static GenSetting> {
        BLOCKS.iter().find_map(|b| {
            b.inst.iter().find_map(|&(_, base)| b.settings.iter().find(|s| base + s.offset == a))
        })
    }

    #[test]
    fn generated_agrees_with_verified_params() {
        for p in PARAMS.iter().chain(crate::modfx::GENERATED.iter()) {
            if let Some(g) = gen_at(p.addr) {
                assert_eq!((g.encoding, g.min, g.max, g.ofs), (p.encoding, p.min, p.max, p.ofs), "{}", p.name);
            }
        }
    }

    #[test]
    fn generated_lists_only_new_settings_with_their_table() {
        assert!(generated().iter().any(|d| d.name == "reverb1-layer-mode"));
        assert!(generated().iter().all(|d| d.name != "delay1-time" && d.name != "gain"));
        assert_eq!(table_of(addr([0x20, 0x00, 0x2E, 0x01])), Some("DELAY"));
        assert_eq!(table_of(addr([0x20, 0x00, 0x56, 0x0A])), Some("EQ_GE10"));
        assert_eq!(table_of(addr([0x20, 0x00, 0x48, 0x00])), None);
    }

    #[test]
    fn known_addresses() {
        assert_eq!(setting("REVERB", 0, "layer-mode").unwrap().addr, addr([0x20, 0x00, 0x34, 0x01]));
        assert_eq!(setting("DELAY", 3, "time").unwrap().name, "delay4-time");
        assert_eq!(setting("DELAY", 1, "time").unwrap().name, "delay2-time");
        assert_eq!(setting("OTHER", 0, "chain").unwrap().max, 8);
        assert_eq!(setting("EQ_GE10", 1, "31hz").unwrap().addr, addr([0x20, 0x00, 0x56, 0x00]));
        assert_eq!(setting("FX_DETAIL", 0, "2x2chorus-low-rate").unwrap().name, "mod1-chorus-low-rate");
        assert_eq!(setting("AMP", 0, "resonance").unwrap().addr, addr([0x20, 0x00, 0x06, 0x08]));
        assert!(BLOCKS.iter().all(|b| b.table != "PEDALFX"));
    }

    #[test]
    fn reverb_time_shows_seconds() {
        let t = setting("REVERB", 0, "time").unwrap();
        assert_eq!((t.min, t.max, t.ofs), (0, 99, -1));
        assert_eq!(crate::format_value(t, 29), "3.0 s");
    }

    #[test]
    fn chorus_settings_are_typed() {
        let fx = gen_block("FX_DETAIL");
        let chorus: Vec<_> = fx.settings.iter().filter(|s| s.key.starts_with("2x2chorus-")).collect();
        assert!(!chorus.is_empty());
        assert!(chorus.iter().all(|s| s.types == [23]), "{chorus:?}");
    }

    #[test]
    fn spring_color_is_a_spring_setting() {
        let rev = gen_block("REVERB");
        assert_eq!(rev.settings.iter().find(|s| s.key == "spring-color").unwrap().types, [3]);
        assert!(rev.settings.iter().find(|s| s.key == "time").unwrap().types.is_empty());
    }
}
